{
  "id": "climate-change-key-data",
  "title": "全球气候变化的关键数据",
  "subtitle": "从冰芯气泡到碳预算——用数据读懂正在变暖的地球",
  "language": "zh-CN",
  "audience": "高中至大学本科，对气候科学有基础兴趣的学习者",
  "theme": "lab",
  "tutor": {
    "suggestions": [
      "为什么说 1998-2012 年的'变暖暂停'是统计陷阱？如果换一个起点年会怎样？",
      "CO₂ 只占大气 0.04%，它的温室效应为什么不能按占比来理解？",
      "海洋热含量比地表气温更能反映地球净能量收支，原因是什么？",
      "剩余碳预算约 500GtCO₂ 按当前速度约 12 年用完，1.5°C 目标还有意义吗？"
    ],
    "kb": [
      {
        "pattern": "辐射强迫|radiative forcing",
        "answer": "温室气体浓度变化引起的地球辐射收支失衡，单位 W/m²。CO₂ 从 280ppm 升至 420ppm 的辐射强迫约 2.7W/m²，公式为 ΔF=5.35×ln(C/C₀)。"
      },
      {
        "pattern": "airborne fraction|碳滞留比|碳滞留",
        "answer": "人为排放的 CO₂ 中留在大气中的比例，目前约 44%，其余 56% 被海洋和陆地碳汇吸收。碳汇效率随海洋酸化和升温在下降。"
      },
      {
        "pattern": "ECS|气候敏感度|equilibrium climate sensitivity",
        "answer": "CO₂ 浓度翻倍（相对工业化前）后地球达到新平衡时的全球平均温升，IPCC AR6 估算范围 2.5-4°C，是预测未来温升最关键的不确定性来源。"
      },
      {
        "pattern": "冰芯|ice core|同位素测年|δ¹⁸O",
        "answer": "从极地冰盖钻取的冰柱，气泡封存远古大气样本可直接测 CO₂，δ¹⁸O 同位素比值反映当时温度。Vostok 和 EPICA 冰芯覆盖了过去 80 万年。"
      },
      {
        "pattern": "剩余碳预算|remaining carbon budget",
        "answer": "在给定温控目标（如 1.5°C）和概率（如 50%）下，人类还能排放的 CO₂ 总量。2024 年初 1.5°C（50%）预算约 500GtCO₂，按当前 ~40GtCO₂/年约 12 年用完。"
      },
      {
        "pattern": "均一化|homogenization|数据拼接",
        "answer": "对气象站记录进行迁站订正、城市热岛效应剔除、仪器更换校准等处理，消除非气候因素导致的人为跳变，使长期趋势可比。"
      }
    ]
  },
  "scenes": [
    {
      "id": "cover",
      "kind": "hero",
      "notes": "本课不讲'气候变暖是不是真的'——那在科学上已无争议。我们要讲的是：那些支撑结论的关键数据从哪来、怎么测、怎么算、怎么被误读。四个视角贯穿全课：数据溯源（冰芯到卫星）、物理机制（辐射强迫到碳循环）、政策工程（碳预算到减排路径）、批判思维（统计陷阱到媒体误读）。",
      "blocks": [
        {
          "id": "b_cover",
          "type": "hero",
          "intent": "封面：全球气候变化的关键数据——从冰芯气泡到碳预算",
          "size": "xl"
        }
      ]
    },
    {
      "id": "paleoclimate",
      "kind": "content",
      "eyebrow": "数据溯源",
      "headline": "冰芯里的八十万年：古气候如何被重构",
      "lead": "没有仪器记录的远古，气候数据来自冰芯气泡与同位素温度计。",
      "notes": "Vostok 和 EPICA 冰芯直接抽取了远古大气样本——气泡里的 CO₂ 就是当时大气的化石。δ¹⁸O 同位素充当温度计：温度越高，轻同位素越易蒸发，降雪中 δ¹⁸O 比值越高。注意冰芯数据的时间分辨率是几十年到几百年量级，不能和现代仪器记录的年际变化直接比分辨率。古气候变暖速度'史无前例'的判断，基于相同时间分辨率下的对比。过去 80 万年 CO₂ 在 180-300ppm 间自然波动，而如今 420ppm 已远超自然上限。",
      "blocks": [
        {
          "id": "b2_chart",
          "type": "chart",
          "intent": "过去 80 万年 Vostok/EPICA 冰芯的 CO₂ 浓度（ppm）与温度异常（°C）同图对比，展示自然波动范围与当前 420ppm 的突破",
          "size": "l"
        },
        {
          "id": "b2_callout",
          "type": "callout",
          "intent": "为什么以 1850-1900 年为工业化前基准：这是全球可靠仪器记录的起点，此前人类化石燃料排放可忽略不计",
          "size": "s"
        },
        {
          "id": "b2_list",
          "type": "list",
          "intent": "冰芯测年三件套：气泡气体定年（封存大气）、δ¹⁸O 同位素温度计（温度代理）、火山灰层（绝对时间锚点）",
          "size": "m"
        }
      ]
    },
    {
      "id": "modern-temp",
      "kind": "content",
      "eyebrow": "数据测量",
      "headline": "从气象站到卫星：现代温度记录如何拼接",
      "lead": "全球平均温度只比工业革命前高 1.1°C——这个数字背后是数万个测站与卫星数据的均一化处理。",
      "notes": "1.1°C 听起来小，但它是全球平均——陆地升温约 1.5-2°C，北极升温 3-4°C（极地放大效应）。均一化处理是关键：一个气象站从城郊搬到市中心，温度记录会跳升，这不是气候变了而是环境变了，必须订正。卫星和地面站趋势'相反'的说法需要区分层次：卫星测的平流层确实在降温（温室效应预测的签名——平流层冷却对流层变暖），对流层在升温，与地面站一致。从噪音中提取信号的核心方法：30 年滑动平均，短期波动是天气，长期趋势才是气候。",
      "blocks": [
        {
          "id": "b3_chart",
          "type": "chart",
          "intent": "1850-2023 年全球温度异常值散点+30 年滑动平均趋势线，标注 1998 厄尔尼诺年与所谓'暂停'区间",
          "size": "l"
        },
        {
          "id": "b3_callout",
          "type": "callout",
          "intent": "卫星测平流层降温、对流层升温——趋势相反恰好是温室效应的理论预测签名，不是数据矛盾",
          "size": "s"
        },
        {
          "id": "b3_list",
          "type": "list",
          "intent": "均一化处理三步：迁站/仪器变更订正、城市热岛效应剔除、海洋船舶观测向浮标数据对齐",
          "size": "m"
        }
      ]
    },
    {
      "id": "radiative-forcing",
      "kind": "content",
      "eyebrow": "物理机制",
      "headline": "0.04%的 CO₂ 如何驱动全球变暖",
      "lead": "CO₂ 的温室效应不取决于它在大气中的占比，而取决于它吸收红外辐射的谱线强度。",
      "transition": "zoom",
      "notes": "这是全课最需要具象锚点的难点。0.04% 的直觉陷阱在于：我们以为气体的效应和它的占比成正比。但 CO₂ 的温室效应取决于它在 15μm 红外波段的吸收带，恰好对应地表热辐射的峰值波长。公式 ΔF=5.35×ln(C/C₀) 告诉我们：CO₂ 从 280 到 420ppm，辐射强迫约 2.7W/m²——相当于整个地球表面每平方米多了一盏 2.7 瓦的灯泡持续加热。水蒸气确实效应更强，但大气停留时间仅 10 天，温度降下来就凝结——它是放大 CO₂ 效应的反馈，不是独立驱动。历史上 CO₂ 滞后温度变化是因为米兰科维奇循环先改变温度、再改变碳循环，但这次是人类直接排放 CO₂ 驱动温度，因果关系方向反了。",
      "blocks": [
        {
          "id": "b4_formula",
          "type": "formula",
          "intent": "辐射强迫公式 ΔF = 5.35 × ln(C/C₀)，C₀ 取工业化前 280ppm，当前 C=420ppm 时 ΔF≈2.7W/m²",
          "size": "s"
        },
        {
          "id": "b4_sim",
          "type": "sim",
          "intent": "调节 CO₂ 浓度（280-560ppm），实时看辐射强迫 ΔF 和对应平衡温升的变化曲线",
          "size": "m"
        },
        {
          "id": "b4_callout",
          "type": "callout",
          "intent": "水蒸气是反馈而非驱动：大气停留时间仅 10 天，无法自己维持长期变暖，但会放大 CO₂ 效应约一倍",
          "size": "s"
        },
        {
          "id": "b4_list",
          "type": "list",
          "intent": "CO₂ 驱动变暖逻辑链：吸收 15μm 红外辐射→平流层冷却对流层变暖→水蒸气反馈放大→冰雪反照率反馈再放大",
          "size": "m"
        }
      ]
    },
    {
      "id": "ocean-carbon",
      "kind": "content",
      "eyebrow": "圈层耦合",
      "headline": "海洋：地球能量收支的真实账本",
      "lead": "地表气温只反映了约 2% 的额外热量，海洋热含量才是地球净能量收支的可靠度量。",
      "notes": "海洋吸收了气候系统约 90% 的额外热量。地表气温年际波动大（±0.2°C），容易被噪音掩盖信号；而 OHC 的变化单调递增，因为水的比热容大、热惯性大，年际波动小得多。airborne fraction 约 44% 意味着：人类每排放 100 吨碳，约 44 吨留在大气推高浓度，56 吨被海洋和陆地碳汇吸收。但碳汇效率在下降——海洋酸化降低吸收能力，永久冻土释放可能形成正反馈。ECS 是预测未来温升最大的不确定性来源：如果 ECS 是 4°C 而非 2.5°C，同样碳预算对应的温升高 60%。",
      "blocks": [
        {
          "id": "b5_chart",
          "type": "chart",
          "intent": "1960-2023 年海洋热含量（0-2000m）累积变化柱状图，显示持续加速增热",
          "size": "l"
        },
        {
          "id": "b5_stats",
          "type": "stats",
          "intent": "关键通量数字：人为排放 ~40GtCO₂/年、airborne fraction ~44%、自然碳汇吸收 ~56%、海洋吸热占比 ~90%",
          "size": "s"
        },
        {
          "id": "b5_callout",
          "type": "callout",
          "intent": "ECS 气候敏感度估算范围 2.5-4°C：CO₂ 浓度翻倍对应的平衡温升，是预测未来温升最关键的未知数",
          "size": "m"
        }
      ]
    },
    {
      "id": "carbon-budget",
      "kind": "content",
      "eyebrow": "政策工程",
      "headline": "剩余碳预算：1.5°C 目标还剩多少时间",
      "lead": "从 2024 年初起，1.5°C 目标（50% 概率）的剩余碳预算约 500GtCO₂，按当前排放速度约 12 年用完。",
      "notes": "剩余碳预算是政策讨论中最硬的数字。500GtCO₂ 按当前 ~40GtCO₂/年排放速度约 12 年用完——这就是为什么说 1.5°C 窗口正在关闭。但'没戏了'不等于'没意义'：每 0.1°C 都意味着可量化的灾害差异。历史责任的核心数据：美国 1850-2022 累计排放约 500GtCO₂，中国约 300GtCO₂——但中国当前年排放约 11GtCO₂，是美国（5Gt）的两倍多。SSP 情景不是预测而是'如果…那么…'的路径分析：SSP1-1.9 假设全球 2050 净零+大规模 CDR，SSP5-8.5 假设化石燃料持续高增长。CDR/CCS 在 SSP1-1.9 中承担约 20% 的减排权重——这意味着即使净零也需要大量碳移除。",
      "blocks": [
        {
          "id": "b6_chart",
          "type": "chart",
          "intent": "主要国家历史累计排放(1850-2022) vs 当前年排放占比对比柱状图",
          "size": "l"
        },
        {
          "id": "b6_callout",
          "type": "callout",
          "intent": "中国当前年排放第一（~30%），但历史累计美国第一（~20%）；碳预算分配的公平性争论核心",
          "size": "s"
        },
        {
          "id": "b6_list",
          "type": "list",
          "intent": "SSP 情景路径：SSP1-1.9 需 2050 净零+大规模 CDR；SSP1-2.6 需 2070 净零；SSP5-8.5 是'一切照旧'高排放路径",
          "size": "m"
        }
      ]
    },
    {
      "id": "media-literacy",
      "kind": "content",
      "eyebrow": "批判思维",
      "headline": "气候数据如何被断章取义",
      "lead": "'全球变暖暂停'是最经典的统计陷阱：挑选 1998 强厄尔尼诺年作起点，任何后续趋势都会显得平缓。",
      "notes": "1998 年是 20 世纪最强厄尔尼诺年，全球温度异常跳高。以它为起点看后续 10-15 年，趋势确实显得平缓——但这是统计陷阱：起点选了异常高的值。换 2012 年或 2015 年起点，'暂停'消失。IPCC 的'极可能'（very likely）=90% 以上概率，'可能'（likely）=66% 以上——这些词有严格定义，不是日常口语。媒体说'海平面上升几十米'引用的是格陵兰+南极冰盖全部融化的地质时间尺度结果（数千年），而 IPCC 对 2100 年的预估是 0.3-1.0 米——时间尺度完全不同。'今年冬天这么冷'混淆了天气（短期局部）与气候（长期全球）：一个冷冬不改变全球平均温度的上升趋势。",
      "blocks": [
        {
          "id": "b7_compare",
          "type": "compare",
          "intent": "误导性表述 vs 正确表述：'变暖暂停了'↔'1998-2012 短期噪音未改变长期趋势'；'海平面上升几十米'↔'2100 年 IPCC 预估 0.3-1.0 米'；'气候一直在变'↔'自然变化速率远低于当前人为变暖'",
          "size": "l"
        },
        {
          "id": "b7_callout",
          "type": "callout",
          "intent": "IPCC 信度语言：'极可能'=>90% 以上概率，'可能'=>66% 以上——不是日常口语的'大概'",
          "size": "s"
        },
        {
          "id": "b7_list",
          "type": "list",
          "intent": "三个常见数据陷阱：cherry-picking 起点年、混淆天气与气候、绝对值 vs 变化率（海平面毫米数 vs 冰川融化百分比）",
          "size": "m"
        }
      ]
    },
    {
      "id": "quiz",
      "kind": "quiz",
      "headline": "随堂检验",
      "notes": "检验学生对关键数据来源、物理机制和统计陷阱的理解。重点考察：辐射强迫公式的含义而非计算、基准期选择的逻辑、airborne fraction 的概念、剩余碳预算的紧迫性、数据选取陷阱的识别。可设 3-4 道客观题+1 道开放讨论题。",
      "blocks": [
        {
          "id": "bq",
          "type": "quiz",
          "intent": "考察：辐射强迫为何不与 CO₂ 占比成正比、1850-1900 基准期的选择逻辑、airborne fraction 约 44% 的含义、剩余碳预算 500GtCO₂ 的紧迫性、1998 年起点陷阱的识别",
          "size": "m"
        }
      ]
    }
  ]
}
